// Единая нормализация: сайт + Telegram -> один формат для RAG
const items = $input.all().map(i => {
  const b = i.json.body ?? i.json;
  const platform = String(b.platform || 'site').toLowerCase();
  const session = String(b.session || b.session_id || '').slice(0, 80);
  const lang = String(b.lang || b.detected_language || 'en').slice(0, 2);
  const text = String(b.message || b.text || '').slice(0, 2000);
  const chat_id = platform === 'telegram'
    ? String(b.session_id || b.chat_id || '').slice(0, 80)
    : (session ? `site:${session}` : 'site:anon');
  return {
    json: {
      text,
      chat_id,
      platform,
      bot_id: b.bot_id,
      detected_language: lang || 'en',
      session,
      lang: b.lang || lang,
      tz: b.tz,
      ip: b.ip,
      userAgent: b.userAgent,
    }
  };
});
return items;

const items = $input.all();
return items.map(i => {
  const reply = String(i.json.formatted_reply ?? i.json.output ?? i.json.answer ?? '').trim();
  return {
    json: {
      reply,                          // для фронта (показывается в чате)
      answer: reply,                  // дублируем
      contacts: i.json.contacts ?? {},
      sources: i.json.sources ?? [],
      detected_language: i.json.detected_language ?? 'en'
    }
  };
});

// Форматируем ответ и ДОБАВЛЯЕМ кликабельные контакты из json.contacts
const out = [];
for (const item of $input.all()) {
  const lang = item.json.detected_language || item.json.lang || 'en';
  const contacts = item.json.contacts || {};
  let text = String(item.json.output || item.json.answer || '').trim();

  if (!text) {
    out.push({ json: { formatted_reply: 'Спасибо! Скоро ответим.', detected_language: lang } });
    continue;
  }

  // 1) Списки '*' → '• '
  text = text.replace(/^\s*\*\s+/gm, '• ');

  // 2) Ссылки: сначала собираем URL-ы, чтобы не сломать экранирование
  const urls = [];
  text = text.replace(/(https?:\/\/[^\s<>\"']+)/gi, m => {
    const u = m.replace(/[.,;:!?]+$/, '');
    const ph = `__URL__${urls.length}__`;
    urls.push(u);
    return ph;
  });

  // 3) Экранирование HTML
  const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;');
  text = esc(text);

  // 4) Вернём URL-ы как кликабельные ссылки
  urls.forEach((u, i) => {
    text = text.replace(`__URL__${i}__`, `<a href="${u}" target="_blank" rel="noopener noreferrer">${esc(u)}</a>`);
  });

  // 5) Markdown bold
  text = text.replace(/\*\*([^*]+?)\*\*/g, '<strong>$1</strong>');

  // 6) Переносы
  text = text.replace(/\n\n+/g, '<br><br>').replace(/\n/g, '<br>').replace(/<br>\s*•\s*/g, '<br>• ');

  // 7) Контакты → кликабельные блоки
  const parts = [text];
  const phones = Array.isArray(contacts.phones) ? contacts.phones : [];
  const emails = Array.isArray(contacts.emails) ? contacts.emails : [];
  const telegram = Array.isArray(contacts.telegram) ? contacts.telegram : [];
  const sites = Array.isArray(contacts.sites) ? contacts.sites : [];

  const hasAny =
    phones.length + emails.length + telegram.length + sites.length > 0;

  if (hasAny) {
    const section = [];

    if (telegram.length) {
      section.push('• Telegram: ' + telegram.map(t => {
        const u = /^https?:\/\//i.test(t) ? t : `https://t.me/${t.replace(/^@/,'')}`;
        return `<a href="${u}" target="_blank" rel="noopener noreferrer">${esc(t)}</a>`;
      }).join(', '));
    }
    if (sites.length) {
      section.push('• Сайты: ' + sites.map(s => {
        const u = /^https?:\/\//i.test(s) ? s : `https://${s}`;
        return `<a href="${u}" target="_blank" rel="noopener noreferrer">${esc(s)}</a>`;
      }).join(', '));
    }
    if (phones.length) {
      section.push('• Телефоны: ' + phones.map(p => {
        const tel = String(p).replace(/\s+/g,'');
        return `<a href="tel:${esc(tel)}">${esc(p)}</a>`;
      }).join(', '));
    }
    if (emails.length) {
      section.push('• Email: ' + emails.map(e => `<a href="mailto:${esc(e)}">${esc(e)}</a>`).join(', '));
    }

    parts.push('<br><br><strong>Контакты для покупки:</strong><br>' + section.join('<br>'));
  }

  out.push({ json: { formatted_reply: parts.join(''), detected_language: lang } });
}
return out;

