const input = $input.all();
if (!Array.isArray(input) || input.length === 0) {
  return [{ json: { answer: '', contacts: {}, sources: [], detected_language: 'en' } }];
}

const out = [];
for (const item of input) {
  let text = String(item.json.output ?? item.json.answer ?? item.json.text ?? '').trim();
  text = text.replace(/```json/gi, '').replace(/```/g, '').replace(/<br\s*\/?>/gi, '\n').trim();

  let data;
  try { data = JSON.parse(text); }
  catch { data = { answer: text, contacts: {}, sources: [] }; }

  out.push({
    json: {
      output: data.answer ?? '',
      answer: data.answer ?? '',
      contacts: data.contacts ?? {},
      sources: data.sources ?? [],
      detected_language: item.json.detected_language ?? item.json.lang ?? 'en'
    }
  });
}
return out;

const out = [];
for (const item of $input.all()) {
  let text = String(item.json.formatted_reply || item.json.reply || item.json.answer || '').trim();
  text = text.replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n').replace(/<[^>]+>/g, '');
  text = text.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>');
  text = text.replace(/\n{3,}/g, '\n\n').trim().slice(0, 4000);
  const chat_id = $('Extract Message Data').item.json.chat_id;
  out.push({ json: { telegram_text: text || 'Спасибо! Скоро ответим.', chat_id } });
}
return out;
